SELECT COALESCE(SUM(ABS(quantity)), 0) AS movement_quantity
FROM agent_v3_stock_movement_view
WHERE agent_v3_stock_movement_view.store_id = ANY(:allowedStoreIds) AND agent_v3_stock_movement_view.occurred_at >= :startAt AND agent_v3_stock_movement_view.occurred_at < :endAt AND (quantity < 0) LIMIT 1;
